// Accept body: { posts: [ { platform, text, hashtags, cta } ] }
// Or single post fields at top level
const body = $input.first().json.body || $input.first().json;
let posts = body.posts || body.social_posts || [];

if (!Array.isArray(posts) || posts.length === 0) {
  // Fallback: treat whole body as one post
  if (body.text) {
    posts = [{ platform: body.platform || 'x', text: body.text, hashtags: body.hashtags || [] }];
  }
}

if (!posts.length) {
  throw new Error('No posts found. Send JSON: { \

 } ] }');
}

// Normalize + pick best posts for each platform
const normalized = posts.map(p => {
  const tags = (p.hashtags || []).map(h => h.startsWith('#') ? h : '#' + h).join(' ');
  let text = (p.text || '').trim();
  if (tags && !text.includes('#')) text = text + '\n' + tags;
  if (p.cta && !text.includes(p.cta)) text = text + '\n' + p.cta;
  // Prefer PriceBD URL
  if (!text.includes('pricebd') && !text.includes('http')) {
    text = text + '\nhttps://pricebd.lovable.app';
  }
  return {
    platform: (p.platform || 'x').toLowerCase(),
    text: text.slice(0, 280), // X limit safe
    text_long: text.slice(0, 2000), // FB allows longer
  };
});

const xPost = normalized.find(p => p.platform === 'x' || p.platform === 'twitter') || normalized[0];
const fbPost = normalized.find(p => p.platform === 'facebook' || p.platform === 'fb') || normalized[0];

return [
  { json: { x_text: xPost.text, fb_text: fbPost.text_long, all: normalized, count: normalized.length } }
];

// Demo posts when using schedule without webhook payload
